using System;

namespace AdoGen.PostgreSql;

/// <summary>
/// Assembly-wide naming conventions for PostgreSQL models generated by AdoGen.
/// </summary>
/// <example><c>[assembly: NpgsqlNaming(Pluralize = false)]</c></example>
[AttributeUsage(AttributeTargets.Assembly, AllowMultiple = false)]
public sealed class NpgsqlNamingAttribute : Attribute
{
    /// <summary>
    /// When true (default) the table name is the pluralized type name (<c>User</c> → <c>Users</c>).
    /// When false the type name is used as-is. A profile's <c>Table(...)</c> call always wins.
    /// </summary>
    public bool Pluralize { get; set; } = true;
}
